async function preSeedRejection(item, mode) {
  // Conversación desechable con el estado requerido: INSERT no pasa por el
  // trigger FSM (BEFORE UPDATE). Vinculada al lead QA para que Snapshot After
  // la resuelva (ORDER BY updated_at DESC) y con los chatwoot ids reales para
  // que CRIS-01 la encuentre al procesar el inbound.
  const stateByMode = { no_moment: 'CONTACTED_1', text_no_interest: 'QUOTED', loss_reason: 'LOSS_REASON_PENDING' };
  const state = stateByMode[mode];
  const seed = { seeded: false, conv_id: null, followup_id: null, errors: [] };
  if (!state || !item.lead_id) { seed.errors.push('missing state or lead_id'); return seed; }
  try {
    const convRows = await __salesProdHttpRequest.call(this, {
      method: 'POST',
      url: QA_SB_URL + '/rest/v1/conversaciones',
      headers: { ...QA_SB_H, Prefer: 'return=representation' },
      body: JSON.stringify({
        lead_id: item.lead_id,
        marca: (item.marca || 'KIA').toUpperCase(),
        canal: 'WHATSAPP',
        estado: state,
        telefono: item.telefono_1 || item.phone,
        nombre: item.nombre_cliente || 'Cliente QA',
        modelo: item.modelo || null,
        chatwoot_conv_id: item.chatwoot_conv_id || null,
        chatwoot_contact_id: item.chatwoot_contact_id || null,
        ultima_respuesta_at: new Date().toISOString()
      })
    });
    const conv = Array.isArray(convRows) ? convRows[0] : convRows;
    if (!conv?.id) { seed.errors.push('conversation insert returned no id'); return seed; }
    seed.conv_id = conv.id;
    const memPatch = {
      conversation_id: conv.id,
      conversation_state: state,
      customer_engaged: mode !== 'no_moment',
      outbound_sequence_status: 'ACTIVE',
      followup_at: null,
      loss_reason_code: null,
      last_customer_decision: null,
      selected_plan: mode === 'text_no_interest' ? 'PLAN_1_YEAR' : null,
      last_response_type: mode === 'text_no_interest' ? 'PRICE_PRESENTED' : null,
      updated_at: new Date().toISOString()
    };
    if (mode === 'no_moment') memPatch.last_inbound_message_at = null;
    await __salesProdHttpRequest.call(this, {
      method: 'PATCH',
      url: QA_SB_URL + '/rest/v1/lead_memory?phone=eq.' + encodeURIComponent(item.phone_e164 || item.phone),
      headers: { ...QA_SB_H, Prefer: 'return=minimal' },
      body: JSON.stringify(memPatch)
    });
    if (mode === 'no_moment') {
      const fuRows = await __salesProdHttpRequest.call(this, {
        method: 'POST',
        url: QA_SB_URL + '/rest/v1/scheduled_followups',
        headers: { ...QA_SB_H, Prefer: 'return=representation' },
        body: JSON.stringify({
          conversation_id: conv.id,
          tipo_followup: 'CONTACTED_2',
          status: 'PENDING',
          scheduled_at: new Date(Date.now() + 60 * 60 * 1000).toISOString()
        })
      }).catch(e => { seed.errors.push('followup:' + String(e.message || e).slice(0, 120)); return null; });
      const fu = Array.isArray(fuRows) ? fuRows[0] : fuRows;
      if (fu?.id) seed.followup_id = fu.id;
    }
    seed.seeded = true;
  } catch (e) {
    seed.errors.push(String(e.message || e).slice(0, 200));
  }
  return seed;
}

