  return { json: { ...item, final_status: status, final_severity: severity, assertions, actual, finding, final_error: caseJson.execute_error || (hardFails.length ? hardFails.map(f => f.id).join('; ') : null), execution_ids_final: caseJson.execution_ids_new || [] } };
});

const rows = $input.all().map(i => i.json);
const runId = rows[0]?.run_id || $('PG - Create Test Run').first().json.run_id;
const counts = rows.reduce((acc, r) => { acc.total++; acc[String(r.status || 'UNKNOWN').toLowerCase()] = (acc[String(r.status || 'UNKNOWN').toLowerCase()] || 0) + 1; if (r.finding_id) acc.findings++; return acc; }, { total: 0, passed: 0, failed: 0, skipped: 0, findings: 0 });
